/**
 * @name Path traversal vulnerability
 * @description Using user-controlled input in file paths can allow access to arbitrary files
 * @kind path-problem
 * @problem.severity error
 * @id py/click-path-traversal
 * @tags security
 *        external/cwe/cwe-022
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.dataflow.new.RemoteFlowSources
import semmle.python.Concepts

module PathTraversalConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    source instanceof RemoteFlowSource or
    exists(DataFlow::ParameterNode param | 
      source = param and
      param.getParameter().getName() in ["path", "filename", "file", "dir", "directory", "name"]
    )
  }

  predicate isSink(DataFlow::Node sink) {
    exists(FileSystemAccess fa | 
      sink = fa.getAPathArgument()
    )
  }
}

module PathTraversalFlow = TaintTracking::Global<PathTraversalConfig>;
import PathTraversalFlow::PathGraph

from PathTraversalFlow::PathNode source, PathTraversalFlow::PathNode sink
where PathTraversalFlow::flowPath(source, sink)
select sink.getNode(), source, sink, "Potential path traversal from $@.", source.getNode(), "user input"

/**
 * @name Shell injection via glob expansion
 * @description Using glob with untrusted input can lead to shell injection
 * @kind path-problem
 * @problem.severity error
 * @id py/click-glob-injection
 * @tags security
 *        external/cwe/cwe-078
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.ApiGraphs

module GlobInjectionConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    exists(DataFlow::ParameterNode param | 
      source = param and
      param.getParameter().getName() in ["pattern", "path", "filename", "name", "args", "arg"]
    )
  }

  predicate isSink(DataFlow::Node sink) {
    exists(DataFlow::CallCfgNode call |
      call = API::moduleImport("glob").getMember(["glob", "iglob"]).getACall() and
      sink = call.getArg(0)
    )
  }
}

module GlobInjectionFlow = TaintTracking::Global<GlobInjectionConfig>;
import GlobInjectionFlow::PathGraph

from GlobInjectionFlow::PathNode source, GlobInjectionFlow::PathNode sink
where GlobInjectionFlow::flowPath(source, sink)
select sink.getNode(), source, sink, "Potential shell injection via glob from $@.", source.getNode(), "user input"
